package com.media.transcoder.desktop;

import com.fasterxml.jackson.databind.JsonNode;
import com.media.transcoder.shared.Json;
import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import javax.swing.filechooser.FileNameExtensionFilter;
import java.io.File;
import java.net.http.HttpRequest.BodyPublisher;
import java.net.http.HttpRequest.BodyPublishers;
import java.nio.file.Files;
import java.util.concurrent.CompletableFuture;

public class Dashboard {
    private final String baseUrl;
    private final DefaultTableModel tableModel=new DefaultTableModel(new String[]{"ID","Arquivo","Status","Perfis","360p","480p","720p"},0){@Override public boolean isCellEditable(int r,int c){return false;}};
    private final JTable table=new JTable(tableModel); private final JLabel message=new JLabel(" ");
    public Dashboard(String baseUrl){this.baseUrl=baseUrl;}
    public void show(){if(!SwingUtilities.isEventDispatchThread()){SwingUtilities.invokeLater(this::show);return;}JFrame frame=new JFrame("Transcoder Video — Conversor local");frame.setDefaultCloseOperation(WindowConstants.EXIT_ON_CLOSE);frame.setSize(1150,650);frame.setLocationRelativeTo(null);frame.setLayout(new BorderLayout(10,10));JPanel header=new JPanel(new BorderLayout());header.setBorder(BorderFactory.createEmptyBorder(14,18,10,18));header.add(new JLabel("TRANSCODER · VIDEO",SwingConstants.LEFT),BorderLayout.WEST);header.add(new JLabel("Conversão local com FFmpeg",SwingConstants.RIGHT),BorderLayout.EAST);frame.add(header,BorderLayout.NORTH);frame.add(buildUploadPanel(),BorderLayout.WEST);frame.add(new JScrollPane(table),BorderLayout.CENTER);JPanel footer=new JPanel(new BorderLayout(8,8));footer.setBorder(BorderFactory.createEmptyBorder(8,14,14,14));footer.add(message,BorderLayout.CENTER);JButton refresh=new JButton("Atualizar jobs");refresh.addActionListener(e->load());footer.add(refresh,BorderLayout.EAST);frame.add(footer,BorderLayout.SOUTH);for(int i=4;i<7;i++){int col=i;table.getColumnModel().getColumn(i).setCellRenderer((t,v,selected,focus,row,column)->{JButton button=new JButton("Baixar");button.setEnabled(v instanceof String s&&!s.isBlank());button.addActionListener(e->download((String)v));return button;});}frame.setVisible(true);load();new Timer(4000,e->load()).start();}
    private JPanel buildUploadPanel(){JPanel panel=new JPanel();panel.setPreferredSize(new Dimension(320,0));panel.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createTitledBorder("Novo processamento"),BorderFactory.createEmptyBorder(12,12,12,12)));panel.setLayout(new BoxLayout(panel,BoxLayout.Y_AXIS));JButton select=new JButton("Selecionar vídeo…");JLabel selected=new JLabel("Nenhum arquivo selecionado");JComboBox<String> outputProfiles=new JComboBox<>(new String[]{"360p","480p","720p"});outputProfiles.setSelectedIndex(1);JTextField source=new JTextField("Arquivo próprio",18);JCheckBox consent=new JCheckBox("Confirmo que tenho autorização",true);JButton send=new JButton("Enviar e converter");send.setAlignmentX(Component.LEFT_ALIGNMENT);select.setAlignmentX(Component.LEFT_ALIGNMENT);selected.setAlignmentX(Component.LEFT_ALIGNMENT);panel.add(new JLabel("Origem até 4K · MP4, MOV, MKV, WEBM, AVI"));panel.add(Box.createVerticalStrut(10));panel.add(select);panel.add(selected);panel.add(Box.createVerticalStrut(10));panel.add(new JLabel("Perfil de saída"));panel.add(outputProfiles);panel.add(new JLabel("Origem do arquivo"));panel.add(source);panel.add(consent);panel.add(Box.createVerticalStrut(12));panel.add(send);final File[] chosen={null};select.addActionListener(e->{JFileChooser chooser=new JFileChooser();chooser.setFileFilter(new FileNameExtensionFilter("Vídeos", "mp4","mov","mkv","webm","avi","m4v"));if(chooser.showOpenDialog(panel)==JFileChooser.APPROVE_OPTION){chosen[0]=chooser.getSelectedFile();selected.setText(chosen[0].getName()+" ("+String.format("%.1f MB",chosen[0].length()/1048576d)+")");}});send.addActionListener(e->{if(chosen[0]==null){message.setText("Selecione um vídeo primeiro.");return;}if(!consent.isSelected()){message.setText("Confirme que você tem autorização para usar este vídeo.");return;}sendUpload(chosen[0],source.getText(),(String)outputProfiles.getSelectedItem());});return panel;}
    private void sendUpload(File file,String source,String profile){message.setText("Enviando arquivo e criando job…");CompletableFuture.runAsync(()->{try{String boundary="----Transcoder"+java.util.UUID.randomUUID().toString().replace("-","");var body=new java.io.ByteArrayOutputStream();writeField(body,boundary,"origin",source);writeField(body,boundary,"permission","Confirmada pelo operador");writeField(body,boundary,"profiles",profile);body.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\"file\"; filename=\""+file.getName().replace("\"","")+"\"\r\nContent-Type: application/octet-stream\r\n\r\n").getBytes(java.nio.charset.StandardCharsets.UTF_8));Files.copy(file.toPath(),body);body.write(("\r\n--"+boundary+"--\r\n").getBytes(java.nio.charset.StandardCharsets.UTF_8));var request=HttpRequest.newBuilder(URI.create(baseUrl+"/videos")).header("Content-Type","multipart/form-data; boundary="+boundary).POST(BodyPublishers.ofByteArray(body.toByteArray())).build();var response=HttpClient.newHttpClient().send(request,HttpResponse.BodyHandlers.ofString());SwingUtilities.invokeLater(()->{if(response.statusCode()==202){message.setText("Upload aceito. Job adicionado à fila.");load();}else message.setText("Upload recusado (HTTP "+response.statusCode()+"): "+response.body());});}catch(Exception e){SwingUtilities.invokeLater(()->message.setText("Erro no envio: "+e.getMessage()));}});}
    private void writeField(java.io.OutputStream body,String boundary,String name,String value)throws java.io.IOException{body.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\""+name+"\"\r\n\r\n"+value+"\r\n").getBytes(java.nio.charset.StandardCharsets.UTF_8));}
    private void download(String id){if(id==null||id.isBlank())return;JFileChooser chooser=new JFileChooser();chooser.setSelectedFile(new File("video-convertido.mp4"));if(chooser.showSaveDialog(table)!=JFileChooser.APPROVE_OPTION)return;File target=chooser.getSelectedFile();HttpClient.newHttpClient().sendAsync(HttpRequest.newBuilder(URI.create(baseUrl+"/arquivos/"+id)).GET().build(),HttpResponse.BodyHandlers.ofFile(target.toPath())).thenAccept(response->SwingUtilities.invokeLater(()->message.setText(response.statusCode()==200?"Download concluído: "+target.getName():"Falha no download (HTTP "+response.statusCode()+")"))).exceptionally(error->{SwingUtilities.invokeLater(()->message.setText("Falha no download: "+error.getMessage()));return null;});}
    private void load(){HttpClient.newHttpClient().sendAsync(HttpRequest.newBuilder(URI.create(baseUrl+"/jobs")).GET().build(),HttpResponse.BodyHandlers.ofString()).thenAccept(response->{try{if(response.statusCode()!=200)throw new IllegalStateException("API HTTP "+response.statusCode());JsonNode root=Json.MAPPER.readTree(response.body());SwingUtilities.invokeLater(()->{tableModel.setRowCount(0);for(JsonNode job:root){java.util.Map<String,String> ids=new java.util.HashMap<>();for(JsonNode output:job.path("outputs"))ids.put(output.path("profile").asText(),output.path("id").asText());tableModel.addRow(new Object[]{job.path("id").asText(),job.path("originalName").asText(),job.path("status").asText(),String.join(", ",ids.keySet()),ids.get("360p"),ids.get("480p"),ids.get("720p")});}message.setText("Atualizado agora · "+root.size()+" job(s)");});}catch(Exception e){SwingUtilities.invokeLater(()->message.setText("Falha ao consultar API: "+e.getMessage()));}}).exceptionally(error->{SwingUtilities.invokeLater(()->message.setText("API indisponível: "+error.getMessage()));return null;});}
}
